#!/usr/bin/env python3
"""Observe last Alice probe receipt and Bedrock evidence; strictly read-only."""
import json,os,shlex,subprocess,sys
from pathlib import Path
REMOTE="\nimport json,os,time,math,re,subprocess\nfrom pathlib import Path\nhome=Path.home();root=home/'.alice-bedrock-control'\na={'state':'unverified','connected':False,'coreState':None,'jobActive':False,\n 'receiptStatus':None,'receiptReason':None,'receiptAgeSeconds':None,\n 'targetCell':None,'bdsSamples':None,'lastBdsAgeSeconds':None,\n 'lastBdsPairAgeSeconds':None,'bdsPairTravel':None,'bdsTotalTravel':None,\n 'clientBdsDistance':None,'movingQueued':None,'movingLast10s':None,\n 'probeEventLogCount':0,'probeLastEventState':None,'scoutOutcomeCount':0,\n 'scoutLastReason':None,'navRejectCount':0,'navLastReason':None}\ndef safe(file,limit=8192):\n p=root/file\n if p.is_symlink() or not p.is_file():return {}\n st=p.stat()\n if st.st_uid!=os.getuid() or st.st_mode&0o077 or st.st_size>limit:return {}\n return json.loads(p.read_text())\ntry:\n proc=subprocess.run(['/usr/bin/python3',str(home/'minecraft-ai/scripts/alice-mint.py'),'status'],capture_output=True,text=True,timeout=12)\n if proc.returncode or len(proc.stdout)>20000:raise ValueError('operator_missing')\n owner=json.loads(proc.stdout)\n if owner.get('statusSource')!='current_process' or owner.get('processAlive') is not True:raise ValueError('not_current')\n d=safe('status.json')\n if d.get('producerPid')!=owner.get('pid') or d.get('world')!='Bedrock level' or d.get('serverPort')!=17879:raise ValueError('wrong_world')\n a['state']='observed'\n a['connected']=d.get('connected') is True and d.get('sessionEstablished') is True\n a['coreState']=d.get('state') if d.get('state') in ('IDLE','EXPLORE','SURVIVE','FOLLOW','COMBAT','RECOVER') else 'other'\n a['jobActive']=d.get('job') is not None\n now=int(time.time()*1000)\n m=d.get('movementEvidence') or {}\n for k,out in [('independentSamples','bdsSamples'),('independentPairTravelBlocks','bdsPairTravel'),('independentTravelBlocks','bdsTotalTravel')]:\n  v=m.get(k)\n  if type(v) in (int,float) and 0<=v<10000000:a[out]=v\n for k,out in [('independentAt','lastBdsAgeSeconds'),('independentPreviousAt','lastBdsPairAgeSeconds')]:\n  v=m.get(k)\n  if type(v) is int and 0<=now-v<86400000:a[out]=round((now-v)/1000,2)\n def vec(p):\n  if not isinstance(p,dict) or not all(type(p.get(k)) in (int,float) and math.isfinite(p[k]) for k in ('x','y','z')):return None\n  return [p[k] for k in ('x','y','z')]\n u=vec(d.get('position'));v=vec(m.get('independentLatestFeet'))\n if u and v:a['clientBdsDistance']=round(math.dist(u,v),3)\n r=safe('command-result.json')\n if r.get('action')=='probe_step':\n  a['receiptStatus']=r.get('status') if r.get('status') in ('started','completed','failed','rejected','received') else 'other'\n  a['receiptReason']=r.get('reason') if isinstance(r.get('reason'),str) and re.fullmatch('[a-z][a-z0-9_]{0,70}',r['reason']) else 'other'\n  if type(r.get('updatedAt')) is int and 0<=now-r['updatedAt']<86400000:a['receiptAgeSeconds']=round((now-r['updatedAt'])/1000,2)\n  m0=re.search(r'(-?\\d+),(-?\\d+),(-?\\d+)',str(r.get('message','')))\n  if m0:\n   xyz=[int(x) for x in m0.groups()]\n   if all(abs(k)<30000000 for k in xyz):a['targetCell']=xyz\n inp=safe('outbound-input-audit.json')\n for k in ('movingQueued','movingLast10s'):\n  val=inp.get(k)\n  if type(val) is int and 0<=val<10000000:a[k]=val\n log=(Path('/proc')/str(owner['pid'])/'fd'/'1').resolve(strict=True)\n if log.parent==root and log.name.startswith('operator-') and log.is_file() and log.stat().st_uid==os.getuid() and log.stat().st_mode&0o077==0:\n  with log.open('rb') as f:\n   f.seek(max(0,log.stat().st_size-160000))\n   lines=f.read(160000).decode('utf8','replace').splitlines()\n  for line in lines:\n   if '[Alice probe] BDS-triggered operator probe:' in line:\n    a['probeEventLogCount']+=1\n    x=re.search('\"state\":\"([a-z_]+)\"',line)\n    if x:a['probeLastEventState']=x.group(1)\n   if '[Alice exploration] segment outcome:' in line:\n    a['scoutOutcomeCount']+=1\n    x=re.search('\"reason\":\"([a-z_]+)\"',line)\n    if x:a['scoutLastReason']=x.group(1)\n   if '[Alice navigation] BDS start rejected:' in line:\n    a['navRejectCount']+=1\n    x=re.search('\"reason\":\"([a-z_]+)\"',line)\n    if x:a['navLastReason']=x.group(1)\nexcept (OSError,ValueError,TypeError,KeyError,subprocess.SubprocessError):pass\nprint(json.dumps(a,separators=(',',':')))\n"
def run(output):
 out=Path(output)
 if out.is_symlink() or not out.is_dir():raise ValueError('output')
 obs=None
 try:
  p=subprocess.run(['/usr/bin/ssh','-T','-o','BatchMode=yes','-o','ConnectTimeout=8','-o','StrictHostKeyChecking=yes','tedz@192.168.0.104','/usr/bin/python3 -c '+shlex.quote(REMOTE)],capture_output=True,text=True,timeout=45)
  if p.returncode==0 and len(p.stdout)<3000:obs=json.loads(p.stdout)
 except (OSError,ValueError,subprocess.SubprocessError):pass
 if not isinstance(obs,dict):obs={'state':'unavailable'}
 fd=os.open(out/'probe_receipt_readonly.json',os.O_CREAT|os.O_EXCL|os.O_WRONLY|getattr(os,'O_NOFOLLOW',0),0o600)
 with os.fdopen(fd,'w') as f:json.dump({'audit':'ALICE_PROBE_RECEIPT_READONLY','readOnly':True,'bdsQueriesSent':0,'observation':obs},f,separators=(',',':'));f.write('\n')
 print(json.dumps({'state':obs['state']}))
def selftest():
 assert 'command-result.json' in REMOTE and 'independentSamples' in REMOTE
 print('ALICE_PROBE_READONLY_CONTRACT_PASS')
if __name__=='__main__':
 if sys.argv[1:]==['--self-test']:selftest()
 elif len(sys.argv)==3 and sys.argv[1]=='--read':run(sys.argv[2])
 else:raise SystemExit('usage')
